package com.yeyamo_mobile.api.feed_service.application;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import com.yeyamo_mobile.api.feed_service.application.port.*;import com.yeyamo_mobile.api.feed_service.domain.model.*;
@Service public class FeedProjectionCommandService{private final FeedProjectionPort projections;private final FeedCachePort cache;private final FeedOutboxPort outbox;public FeedProjectionCommandService(FeedProjectionPort p,FeedCachePort c,FeedOutboxPort o){projections=p;cache=c;outbox=o;}
 @Transactional public void content(String eventType,FeedPost post,String correlation){projections.savePost(post);cache.invalidate();outbox.append("feed.post.projected",post.postId().toString(),correlation,Map.of("postId",post.postId(),"available",post.available(),"sourceEvent",eventType));}
 @Transactional public void interaction(String eventType,UUID postId,String user,String correlation){FeedMetric m=projections.metric(postId);long l=0,c=0,s=0,f=0;double weight=0;
  switch(eventType){case"interaction.like.added"->{l=1;weight=2;}case"interaction.like.removed"->{l=-1;weight=-2;}case"interaction.favorite.added"->{f=1;weight=3;}case"interaction.favorite.removed"->{f=-1;weight=-3;}case"interaction.comment.created"->{c=1;weight=1;}case"interaction.comment.deleted"->c=-1;case"interaction.post.shared"->{s=1;weight=2;}default->{return;}}
  projections.saveMetric(m.adjust(l,c,s,f));if(user!=null&&!user.isBlank()&&weight!=0)projections.adjustSignal(user,postId,weight);cache.invalidate();outbox.append("feed.metrics.updated",postId.toString(),correlation,Map.of("postId",postId,"sourceEvent",eventType));}}
